    if tree != want:
        missing = sorted(set(want) - set(tree))
        extra = sorted(set(tree) - set(want))
        changed = sorted(k for k in set(tree) & set(want) if tree[k] != want[k])
        msg = "resulting files differ:"
        if missing:
            msg += f"\n    missing: {[m for m in missing[:5]]}"
        if extra:
